{"command": "# Try the releases index to find .NET 11 info
curl -sf "https://dotnetcli.azureedge.net/dotnet/release-metadata/releases-index.json" | python3 -c "
import json, sys
data = json.load(sys.stdin)
for r in data.get('releases-index', []):
    ver = r.get('channel-version','')
    if ver.startswith('11') or ver.startswith('10') or ver.startswith('9'):
        print(f\"{ver} -> {r.get('releases.json','')}\")" 2>/dev/null | head -20", "description": "Check .NET releases index for version 11"}
